import { expect, test, type Page } from "@playwright/test";
import fs from "node:fs";
import path from "node:path";
import { autoSliceOff } from "./auto-slice";

const beltCube = JSON.parse(fs.readFileSync(path.resolve("e2e/fixtures/cube-belt.json"), "utf8"));

// The head and tail of an engine file for a belt printer that was sent a 90 C bed and a 250 C nozzle.
// It has one `;LAYER:` line for each layer the reply lists, which is how the progress lines find their layer.
const engineGcode = [
  "; generated by Lime Slice — FDM strategy blender",
  "; printer: Ideaformer IR3 V2",
  "; blend: single speed",
  "M140 S90",
  "M104 S250",
  "M190 S90",
  "M109 S250",
  "; estimator: lookahead junction_deviation=0.0200",
  "G21",
  "G90",
  "M82",
  "G28",
  "G92 E0",
  "M106 S0",
  "M204 S1500",
  "; belt: angle 45 axis Z dir +1",
  ...beltCube.layers.flatMap((layer: { index: number }, i: number) => i === 0
    ? [";LAYER:0 Z:0.283 H:0.200", "G1 Z0.283 F7200", "G1 X115.000 Y0.100 F18000", "G1 X115.097 Y0.199 E0.00244 F1800"]
    : [`;LAYER:${layer.index} Z:${(0.283 + 0.2 * i).toFixed(3)} H:0.200`, "G1 X115.097 Y0.199 E0.00244 F1800"]),
  "G1 Z200.000 F600",
  "M106 S0",
  "M104 S0",
  "M140 S0",
  "; TIME:240.0s FILAMENT_MM:709.68 FILAMENT_G:2.117 ARCS:0",
  "M84",
  "",
].join("\n");

async function quiet(page: Page) {
  await page.addInitScript(() => localStorage.setItem("lime-slice-closed-groups", "[]"));
  await page.route("**/api/health", (route) => route.fulfill({ json: { ok: true } }));
  await page.route("**/api/jobs**", (route) => route.fulfill({ status: 404, json: { error: "not found" } }));
  await page.addInitScript(() => {
    Object.defineProperty(window, "showSaveFilePicker", { configurable: true, value: undefined });
  });
}

async function chooseIr3Abs(page: Page) {
  await page.locator("#printerChip").evaluate((el) => { (el as HTMLDetailsElement).open = true; });
  await page.locator("#machinePrinter").selectOption("ideaformer-ir3-v2");
  await page.locator("#machineFilament").selectOption("lime-abs");
}

test("the IR3 V2 with ABS asks for a 90 C bed, says so, and exports a file that starts with PRINT_START", async ({ page }) => {
  await quiet(page);
  const bodies: { printer: { bedTemp: number; nozzleTemp: number } }[] = [];
  await page.route("**/api/slice", async (route) => {
    bodies.push(route.request().postDataJSON());
    await route.fulfill({ json: { ...beltCube, gcode: engineGcode } });
  });
  await page.goto("/");
  await autoSliceOff(page);
  await chooseIr3Abs(page);

  await expect(page.locator("#printerHeatNote")).toHaveText("Bed 90 °C (ABS asks 100 °C, this printer stops at 90 °C)");
  await page.locator("#printerChip").evaluate((el) => { (el as HTMLDetailsElement).open = false; });
  await expect(page.locator("#machineTemps")).toHaveText("Nozzle 250 °C · bed 90 °C");
  await expect(page.locator("#machineHeatNote")).toHaveText("Bed 90 °C (ABS asks 100 °C, this printer stops at 90 °C)");

  await page.evaluate(() => document.querySelector<HTMLButtonElement>('[data-sample="calibration_cube_20mm.stl"]')?.click());
  await expect(page.locator("#slice")).toBeEnabled();
  await page.locator("#slice").click();
  await expect.poll(() => bodies.length).toBe(1);
  expect(bodies[0]!.printer.bedTemp).toBe(90);
  expect(bodies[0]!.printer.nozzleTemp).toBe(250);
  await expect(page.locator("#export")).toHaveAttribute("data-slice", "current");

  const download = page.waitForEvent("download");
  await page.locator("#export").click();
  const file = fs.readFileSync(await (await download).path(), "utf8");
  const lines = file.split("\n");
  const code = lines.filter((line) => !line.startsWith(";") && line !== "");
  expect(code[0]).toBe("PRINT_START");
  expect(lines).toContain("; bed capped at 90 C (filament 100 C)");
  expect(lines).toContain("G28 Y");
  expect(lines).not.toContain("G28");
  expect(lines.some((line) => /^M1[49]0 S100$/.test(line))).toBe(false);
  expect(lines.slice(lines.indexOf("PRINT_START"), lines.indexOf("PRINT_START") + 4)).toEqual(["PRINT_START", "M140 S90", "M104 S250", "M109 S250"]);
  const afterStart = lines.indexOf("M82", lines.indexOf("G28 Y"));
  expect(lines.slice(afterStart + 1, afterStart + 8)).toEqual(["M140 S90", "M104 S250", "M190 S90", "M109 S250", "G90", "M82", "G92 E0"]);
  expect(lines.indexOf(";LAYER:0 Z:0.283 H:0.200")).toBeGreaterThan(afterStart);
  expect(lines.indexOf("PRINT_END")).toBeLessThan(lines.lastIndexOf("M104 S0"));
});

test("an export carries the header, estimates, and progress a printer's file browser reads", async ({ page }) => {
  await quiet(page);
  await page.route("**/api/slice", (route) => route.fulfill({ json: { ...beltCube, gcode: engineGcode } }));
  await page.goto("/");
  await autoSliceOff(page);
  await chooseIr3Abs(page);
  await page.evaluate(() => document.querySelector<HTMLButtonElement>('[data-sample="calibration_cube_20mm.stl"]')?.click());
  await expect(page.locator("#slice")).toBeEnabled();
  await page.locator("#slice").click();
  await expect(page.locator("#export")).toHaveAttribute("data-slice", "current");

  const download = page.waitForEvent("download");
  await page.locator("#export").click();
  const lines = fs.readFileSync(await (await download).path(), "utf8").split("\n");

  // Moonraker reads the slicer from this line.
  expect(lines[0]).toMatch(/^; generated by Lime Slice \d+\.\d+\.\d+\S* on \d{4}-\d{2}-\d{2} at \d{2}:\d{2}:\d{2}$/);
  expect(lines[1]).toBe("; FDM strategy blender");
  const firstCode = lines.findIndex((line) => line !== "" && !line.startsWith(";"));
  expect(lines[firstCode]).toBe("PRINT_START");
  expect(lines.slice(0, firstCode).every((line) => line.startsWith(";"))).toBe(true);

  const progress = lines.filter((line) => line.startsWith("M73 "));
  const percents = progress.map((line) => Number(/^M73 P(\d+) R\d+$/.exec(line)![1]));
  expect(progress[0]).toBe("M73 P0 R4");
  expect(percents.every((p, i) => i === 0 || p >= percents[i - 1]!)).toBe(true);
  expect(progress.at(-1)).toBe("M73 P100 R0");
  expect(lines.indexOf("M73 P100 R0")).toBeLessThan(lines.indexOf("PRINT_END"));

  const tail = lines.slice(lines.findIndex((line) => line.startsWith("; TIME:240.0s FILAMENT_MM:709.68 ")) + 1);
  expect(tail.slice(0, 3)).toEqual(["; estimated printing time (normal mode) = 4m 0s", "; filament used [mm] = 709.68", expect.stringMatching(/^; filament used \[g\] = \d+\.\d\d$/)]);
  expect(tail.slice(3)).toEqual(["; total layers count = 141", "; layer_height = 0.2", "; nozzle_diameter = 0.4", "; filament_type = ABS", "M84", ""]);
});

test("a printer inside its limits shows no warning, and a raised limit lifts the cap", async ({ page }) => {
  await quiet(page);
  await page.goto("/");
  await autoSliceOff(page);
  await expect(page.locator("#machineHeatNote")).toBeHidden();
  await expect(page.locator("#machineTemps")).toHaveText("Nozzle 200 °C · bed 60 °C");
  await chooseIr3Abs(page);
  await page.locator("#printerChip").evaluate((el) => { (el as HTMLDetailsElement).open = false; });
  await expect(page.locator("#machineHeatNote")).toBeVisible();
  await page.locator("#machineMore").evaluate((el) => { (el as HTMLDetailsElement).open = true; });
  await page.locator("#machineMaxBed").fill("100");
  await page.locator("#machineMaxBed").blur();
  await expect(page.locator("#machineTemps")).toHaveText("Nozzle 250 °C · bed 100 °C");
  await expect(page.locator("#machineHeatNote")).toBeHidden();
});
